    def test_get_attribute_by_xpath(self):
        xpath = '//something'
        attr_name = 'attr'
        expect_attr = 'online'
        timeout = 1
        self.common_page._wait_for_element_by = mock.Mock()
        elem = mock.Mock()
        elem.get_attribute = mock.Mock(return_value=expect_attr)
        self.common_page.driver.find_element_by_xpath = mock.Mock(return_value=elem)

        output = self.common_page.get_attribute_by_xpath(xpath, attr_name, timeout)
        self.common_page._wait_for_element_by.assert_called_once_with((By.XPATH, xpath), timeout)
        self.common_page.driver.find_element_by_xpath.assert_called_once_with(xpath)
        elem.get_attribute.assert_called_once_with(attr_name)
        self.assertEqual(output, expect_attr)

