    @patch('taf.ul.oam.selenium_coam.common.common.ActionChains')
    def test_perform_element_hover_by_xpath(self, mock_action_chains):
        xpath = '//xpath'
        elem = mock.Mock()
        self.common_page.driver.find_element_by_xpath = mock.Mock(return_value=elem)
        elem_action = mock.Mock()
        mock_action_chains.return_value = elem_action
        elem_move = mock.Mock()
        elem_action.move_to_element = mock.Mock(return_value=elem_move)
        elem_move.perform = mock.Mock()
        self.common_page.wait_for_visibility = mock.Mock()

        self.common_page.perform_element_hover_by_xpath(xpath)
        self.common_page.wait_for_visibility.assert_called_once_with((By.XPATH, xpath))
        self.common_page.driver.find_element_by_xpath.assert_called_once_with(xpath)
        mock_action_chains.assert_called_once_with(self.common_page.driver)
        elem_action.move_to_element.assert_called_once_with(elem)
        elem_move.perform.assert_called_once()

