    def test_get_dict_from_elements_by_xpath(self):
        key_xpath = "//key"
        value_xpath = "//value"
        separator = ":"
        key_element = mock.MagicMock()
        value_element = mock.MagicMock()
        key_element.text = 'key:'
        value_element.text = 'value'
        expect_return_dict = dict(zip([key_element.text.strip(separator)], [value_element.text]))

        def side_effect(input_xpath):
            return [key_element] if input_xpath == key_xpath else [value_element]

        self.common_page.driver.find_elements_by_xpath = mock.Mock(side_effect=side_effect)

        output = self.common_page.get_dict_from_elements_by_xpath(key_xpath, value_xpath, separator)
        self.common_page.driver.find_elements_by_xpath.assert_has_calls(
            [call.find_elements_by_xpath(key_xpath), call.find_elements_by_xpath(value_xpath)])
        self.assertEqual(output, expect_return_dict)

    def test_load_file_from_hidden_button(self):
        select_element_script = "aaaa"
        xpath = "//xpath"
        file_path = "/dir/file"
        timeout = 1
        self.common_page.display_element = mock.Mock()
        self.common_page.wait_for_enable = mock.Mock()
        elem = mock.Mock()
        elem.clear = mock.Mock()
        elem.send_keys = mock.Mock()
        self.common_page.driver.find_element_by_xpath = mock.Mock(return_value=elem)
        self.common_page.hide_element = mock.Mock()

        self.common_page.load_file_from_hidden_button(select_element_script, xpath, file_path, timeout)
        self.common_page.display_element.assert_called_once_with(select_element_script)
        self.common_page.wait_for_enable.assert_called_once_with((By.XPATH, xpath), timeout)
        self.common_page.driver.find_element_by_xpath.assert_called_once_with(xpath)
        elem.clear.assert_called_once()
        elem.send_keys.assert_called_once_with(file_path)
        self.common_page.hide_element.assert_called_once_with(select_element_script)

